// generarResultadosPPTX.js (con imagen base64 embebida)
import pptxgen from "pptxgenjs"

// Imagen de fondo convertida a base64 (Jaguar)
const fondoBase64 = "data:image/jpeg;base64,"

export const generarResultadosPPTX = (resultados) => {
  const pptx = new pptxgen()
  pptx.author = "Desafío Jaguar"
  pptx.title = "Resultados Finales del Desafío Jaguar"
  pptx.subject = "Clasificación por tiempo total"
  pptx.company = "ISC"

  const ordenados = resultados.sort((a, b) => b.total_ms - a.total_ms)

  const agregarFondo = (slide) => {
    slide.background = { data: fondoBase64 }
    slide.transition = { type: "push", advance: false } // 'push' equivale a 'mostrar' en Office ES
  }

  // Slide de portada
  const portada = pptx.addSlide()
  agregarFondo(portada)
  portada.addText("Resultados del Desafío Jaguar", {
    x: 0.5, y: 2.5, fontSize: 36, bold: true, align: "center", w: "90%", color: "ffffff"
  })
  portada.addText("Clasificación de equipos por tiempo total", {
    x: 0.5, y: 3.2, fontSize: 20, color: "ffffff", align: "center", w: "90%"
  })

  const totalEquipos = ordenados.length

  for (let i = totalEquipos - 1; i >= 0; i--) {
    const puesto = totalEquipos - i
    const e = ordenados[i]
    const slide = pptx.addSlide()
    agregarFondo(slide)

    slide.addText(`${puesto}° lugar: ${e.nombre}`, {
      x: 0.5, y: 0.5, fontSize: 28, bold: true, color: "ffffff", align: "center", w: "90%"
    })

    const tabla = [
      [
        { text: "Equipo", options: { bold: true, fill: "003366", color: "ffffff" } },
        { text: "Tiempo Original", options: { bold: true, fill: "003366", color: "ffffff" } },
        { text: "Tiempo Físico", options: { bold: true, fill: "003366", color: "ffffff" } },
        { text: "Tiempo Total", options: { bold: true, fill: "003366", color: "ffffff" } }
      ],
      [e.nombre, e.original, e.fisico, e.total]
    ]

    slide.addTable(tabla, {
      x: 0.5, y: 1.3, w: 9.0,
      fontSize: 18,
      align: "center",
      rowH: 0.6,
      color: "000000",
      border: { type: "solid", color: "cccccc", pt: 1 }
    })
  }

  // Slide final para el 1er lugar
  const ganador = ordenados[0]
  const final = pptx.addSlide()
  agregarFondo(final)
  final.addText("¡Felicidades al primer lugar!", {
    x: 0.5, y: 2.2, fontSize: 32, bold: true, color: "ffffff", align: "center", w: "90%"
  })
  final.addText(`${ganador.nombre}`, {
    x: 0.5, y: 3.0, fontSize: 42, bold: true, color: "ffff00", align: "center", w: "90%"
  })

  pptx.writeFile("ResultadosJaguar.pptx")
} 
